INSERT INTO connector_inbox (
  id, channel, event_id, payload, status, attempts, created_at, updated_at
) VALUES (
  #{id}, #{channel}, #{eventId}, #{payload}, 'pending', 0, #{createdAt}, #{updatedAt}
)
ON CONFLICT (channel, event_id) DO NOTHING

mapper.select:
SELECT id, channel, event_id, payload, status, attempts, last_error, next_attempt_at, created_at, updated_at
FROM connector_inbox
WHERE id = #{id}

mapper.update:
UPDATE connector_inbox
SET status = 'done', last_error = NULL, next_attempt_at = NULL, updated_at = now()
WHERE id = #{id}

UPDATE connector_inbox
SET status = 'failed', last_error = #{lastError}, next_attempt_at = #{nextAttemptAt}, updated_at = now()
WHERE id = #{id}
